using System;using System.IO;using System.Linq;using LumaDesk;
class CloudChecks {
 static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}static CloudDocument Doc(params CloudEvent[] items){return new CloudDocument{items=items.ToList()};}static CloudEvent Event(string id,string title="Event"){return new CloudEvent{Id=id,Title=title,Kind="alarm",NextLocal="2027-01-02T09:30:00",Sound="@bells",Days=62,Snooze=5};}static bool Throws(Action action){try{action();return false;}catch{return true;}}
 static void Main(){int c;var empty=Doc();var original=Doc(Event("one"));var local=CloudJson.Copy(original);local.items[0].Title="Local";var remote=CloudJson.Copy(original);remote.items[0].Title="Remote";
 Check(CloudMerge.Merge(empty,Doc(Event("a")),Doc(Event("b")),out c).items.Count==2,"independent additions merge");Check(CloudMerge.Merge(original,original,remote,out c).items[0].Title=="Remote","remote edit reaches unchanged client");Check(CloudMerge.Merge(original,local,original,out c).items[0].Title=="Local","local edit retained");Check(CloudMerge.Merge(original,empty,original,out c).items.Count==0,"local deletion propagates");Check(CloudMerge.Merge(original,original,empty,out c).items.Count==0,"remote deletion propagates");Check(CloudMerge.Merge(original,empty,empty,out c).items.Count==0,"both deletions remain deleted");var conflict=CloudMerge.Merge(original,local,remote,out c);Check(conflict.items.Count==2&&c==1,"simultaneous edit keeps two versions");Check(conflict.items.Any(a=>a.Title=="Remote")&&conflict.items.Any(a=>a.Title.StartsWith("Local")),"neither conflicting title lost");var second=CloudMerge.Merge(original,local,remote,out c);Check(CloudJson.Same(conflict,second),"conflict copy IDs deterministic on retry");var editDelete=CloudMerge.Merge(original,local,empty,out c);Check(editDelete.items.Count==1&&editDelete.items[0].Id!="one"&&editDelete.items[0].Title.StartsWith("Local"),"edit versus deletion preserves edited copy");var deleteEdit=CloudMerge.Merge(original,empty,remote,out c);Check(deleteEdit.items.Count==1&&deleteEdit.items[0].Id!="one","deletion versus edit preserves remote copy");Check(CloudMerge.Merge(original,local,local,out c).items.Count==1&&c==0,"same edit is idempotent");
 var baseline=Doc();var ls=CloudJson.Copy(baseline);var rs=CloudJson.Copy(baseline);ls.settings.Opacity=70;rs.settings.Location=new CloudLocation{City="Саров",Lat=54.9228,Lon=43.3448};var settings=CloudMerge.Merge(baseline,ls,rs,out c);Check(settings.settings.Opacity==70&&settings.settings.Location.City=="Саров"&&settings.settings.Location.Lat==54.9228,"settings fields merge and city coordinates stay together");ls.settings.Opacity=60;rs.settings.Opacity=90;Check(CloudMerge.Merge(baseline,ls,rs,out c).settings.Opacity==60,"simultaneous setting edit uses local value");
 var inFlight=Doc(Event("one"));var current=Doc(Event("one"),Event("later"));var accepted=Doc(Event("one"),Event("cloud"));var during=CloudMerge.Merge(inFlight,current,accepted,out c);Check(during.items.Count==3,"edits during network request preserved");var initial=CloudMerge.Initial(Doc(Event("local")),new CloudSnapshot{revision=3,document=Doc(Event("remote"))},false);Check(initial.items.Count==1&&initial.items[0].Id=="remote","first login without import excludes existing local events");initial=CloudMerge.Initial(Doc(Event("local")),new CloudSnapshot{revision=3,document=Doc(Event("remote"))},true);Check(initial.items.Count==2,"first login explicit import combines events");var fresh=Doc();fresh.settings.Opacity=65;Check(CloudMerge.Initial(fresh,new CloudSnapshot(),true).settings.Opacity==65,"new account imports shared preferences");
 var state=new State{Startup=true,Top=true,Locked=true};state.Windows[0].X=123;state.Items.Add(new Item{Id="one",Title="Custom",Sound="C:\\private\\sound.wav",Next=new DateTime(2027,1,2,9,30,0)});var captured=CloudMerge.Capture(state);Check(!CloudJson.Write(captured).Contains("private")&&captured.items[0].Sound=="@dawn","custom local file paths never uploaded");CloudMerge.Apply(state,Doc(Event("one")));Check(state.Windows[0].X==123&&state.Startup&&state.Top&&state.Locked,"device positions and startup retained");Check(state.Items[0].Sound=="C:\\private\\sound.wav","existing custom sound retained locally");Check(state.Items[0].Next==new DateTime(2027,1,2,9,30,0),"local wall clock time survives sync");
 Check(CloudApi.ValidateServer("https://sync.example.com/")=="https://sync.example.com","HTTPS server normalizes");Check(Throws(()=>CloudApi.ValidateServer("http://example.com")),"remote HTTP rejected");Check(CloudApi.ValidateServer("http://127.0.0.1:8765")=="http://127.0.0.1:8765","loopback HTTP allowed for local development");Check(Throws(()=>CloudApi.ValidateServer("https://user:secret@example.com"))&&Throws(()=>CloudApi.ValidateServer("https://example.com/#token")),"credentials and fragments rejected in server URL");
 var fixtureState=new State();fixtureState.Notes.Add(new Note{Id="interopnote",Title="Заметка для синхронизации",Body="Строка 1\nСтрока 2 — заметка"});fixtureState.Items=new System.Collections.Generic.List<Item>{new Item{Id="interop",Title="Русское напоминание",Kind="reminder",Sound="@orbit",Next=new DateTime(2027,1,2,9,30,0)}};File.WriteAllText("cloud-document-fixture.json",CloudJson.Write(CloudMerge.Capture(fixtureState)));Console.WriteLine(n+" client sync checks passed");}
}
